import requests

API_KEY = "YOUR_TMDB_API_KEY"
BASE_URL = "https://api.themoviedb.org/3"

# Find movies directed by Francis Ford Coppola.
people_response = requests.get(
    f"{BASE_URL}/search/person",
    params={"api_key": API_KEY, "query": "Francis Ford Coppola"},
)
people_response.raise_for_status()
people = people_response.json().get("results", [])

if people:
    director_id = people[0]["id"]
    credits_response = requests.get(
        f"{BASE_URL}/person/{director_id}/movie_credits",
        params={"api_key": API_KEY},
    )
    credits_response.raise_for_status()

    directed_movies = [
        movie
        for movie in credits_response.json().get("crew", [])
        if movie.get("job") == "Director"
    ]

    if directed_movies:
        movie = max(directed_movies, key=lambda item: item.get("popularity", 0))
        similar_response = requests.get(
            f"{BASE_URL}/movie/{movie['id']}/similar",
            params={"api_key": API_KEY},
        )
        similar_response.raise_for_status()

        print({
            "based_on": movie.get("title"),
            "similar_movies": [
                {
                    "title": item.get("title"),
                    "release_date": item.get("release_date"),
                    "overview": item.get("overview"),
                }
                for item in similar_response.json().get("results", [])
            ],
        })
    else:
        print("No directed movies found.")
else:
    print("Director not found.")

