import requests

API_KEY = "YOUR_TMDB_API_KEY"
BASE_URL = "https://api.themoviedb.org/3"

titles = ["Avatar", "Avatar: The Way of Water"]
ratings = {}

for title in titles:
    response = requests.get(
        f"{BASE_URL}/search/movie",
        params={"api_key": API_KEY, "query": title},
    )
    response.raise_for_status()
    results = response.json().get("results", [])
    match = next((movie for movie in results if movie.get("title") == title), None)
    if match:
        ratings[title] = match.get("vote_average")

if len(ratings) == 2:
    higher_rated = max(ratings, key=ratings.get)
    print(f"{higher_rated} has the higher rating ({ratings[higher_rated]}).")
else:
    print("Could not find ratings for both movies.")

