import requests

API_KEY = "YOUR_TMDB_API_KEY"
BASE_URL = "https://api.themoviedb.org/3"

def search_person(name):
    response = requests.get(
        f"{BASE_URL}/search/person",
        params={"api_key": API_KEY, "query": name},
    )
    response.raise_for_status()
    results = response.json().get("results", [])
    return results[0] if results else None

yui = search_person("Yui Aragaki")
gen = search_person("Gen Hoshino")

if not yui or not gen:
    print("Could not verify both actors.")
else:
    response = requests.get(
        f"{BASE_URL}/search/tv",
        params={"api_key": API_KEY, "query": "We Married as Job"},
    )
    response.raise_for_status()
    shows = response.json().get("results", [])
    show = next(
        (item for item in shows if item.get("name", "").lower() == "we married as job"),
        shows[0] if shows else None,
    )

    if not show:
        print("TV series not found.")
    else:
        response = requests.get(
            f"{BASE_URL}/tv/{show['id']}/credits",
            params={"api_key": API_KEY},
        )
        response.raise_for_status()
        cast_ids = {
            member.get("id")
            for member in response.json().get("cast", [])
        }
        print(yui["id"] in cast_ids and gen["id"] in cast_ids)
